import{_ as a,Y as i,o as t,c as n,aq as o,H as l}from"./chunks/framework.B5JO4mFd.js";import"./chunks/theme.CepjqQUq.js";const m=JSON.parse('{"title":"R8 & Proguard Obfuscation","description":"","frontmatter":{},"headers":[],"relativePath":"en/config/r8-proguard.md","filePath":"en/config/r8-proguard.md"}'),r={name:"en/config/r8-proguard.md"};function p(h,s,c,d,k,u){const e=i("NolebaseGitChangelog");return t(),n("div",null,[s[0]||(s[0]=o(`<h1 id="r8-proguard-obfuscation" tabindex="-1">R8 &amp; Proguard Obfuscation <a class="header-anchor" href="#r8-proguard-obfuscation" aria-label="Permalink to &quot;R8 &amp; Proguard Obfuscation&quot;">​</a></h1><blockquote><p>In most scenarios, app packages can be compressed through obfuscation. Here is an introduction to how to configure obfuscation rules.</p></blockquote><p>Hikage itself does not require additional obfuscation rules. Since <code>View</code> objects created by Hikage do not need to be declared in XML, their class names can also be obfuscated.</p><h2 id="keep-custom-constructors" tabindex="-1">Keep Custom Constructors <a class="header-anchor" href="#keep-custom-constructors" aria-label="Permalink to &quot;Keep Custom Constructors&quot;">​</a></h2><p>If a custom <code>View</code> is not declared in XML, R8 may remove constructors that it cannot discover directly. To let Hikage continue creating custom <code>View</code>s through the <code>(Context)</code> or <code>(Context, AttributeSet)</code> constructors, add the following rule.</p><p>This rule keeps only the constructors and still allows class names to be obfuscated.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-keep,allowobfuscation class * extends android.view.View {</span></span>
<span class="line"><span>    &lt;init&gt;(...);</span></span>
<span class="line"><span>}</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Tips</p><p>If you are using layout component functions (Hikage Performer) generated by <a href="./../plugin/hikage-gradle-plugin.html">hikage-gradle-plugin</a> or <a href="./../library/hikage-compiler.html">hikage-compiler</a>, the above rule is no longer necessary.</p></div><p>If you provide a custom <code>ViewGroup.LayoutParams</code> and it is only created through Hikage&#39;s <code>LayoutParams</code> DSL, you also need to keep its constructors.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-keep,allowobfuscation class * extends android.view.ViewGroup$LayoutParams {</span></span>
<span class="line"><span>    &lt;init&gt;(...);</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="xml-attribute-set-string-references" tabindex="-1">XML Attribute Set String References <a class="header-anchor" href="#xml-attribute-set-string-references" aria-label="Permalink to &quot;XML Attribute Set String References&quot;">​</a></h2><p><code>HikageAttribute</code> string resource references follow the same form as XML.</p><div class="language-kotlin vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">kotlin</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HikageAttribute</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    app</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dataSets&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;@array/simple_string_data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>This form resolves resources by name at runtime. R8 code obfuscation does not affect it, but if you have <code>isShrinkResources = true</code> configured and the target resource is only referenced through this string, the resource shrinker may consider it unused and remove it.</p><p>You can solve this problem by using direct resource ID references.</p><div class="language-kotlin vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">kotlin</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HikageAttribute</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    app</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dataSets&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, R.array.simple_string_data)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>If you must keep the XML-style string reference, add a resource keep file in the app module, for example <code>res/raw/my_res_keep.xml</code>.</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;?</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">xml</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> encoding</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;utf-8&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">?&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">resources</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> xmlns:tools</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://schemas.android.com/tools&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    tools:keep</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;@array/simple_string_data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p>The same applies to custom <code>attrs.xml</code> enum, flag, and reference values that are only reached through dynamic strings. Use resource IDs where possible, or keep the corresponding resources with <code>tools:keep</code>.</p><div class="warning custom-block"><p class="custom-block-title">Notice</p><p>If you do not include the <a href="./../library/hikage-runtime-attribute.html">hikage-runtime-attribute</a> module because you do not need this feature, you need to configure the following rule to avoid warnings from R8 about missing classes or errors during compilation.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-dontwarn com.highcapable.hikage.runtime.attribute.**</span></span></code></pre></div></div>`,20)),l(e)])}const b=a(r,[["render",p]]);export{m as __pageData,b as default};
